sql.if:
WHERE a.application_no=#{query} OR a.policy_no=#{query}
   OR EXISTS (
     SELECT 1 FROM new_contract.application_party p
      WHERE p.application_no=a.application_no AND p.customer_id=#{query}
   )

mapper.select:
SELECT p.policy_no,p.application_no,p.product_code,u.contract_status_code,p.effective_date, p.created_by,p.created_at,p.updated_by,p.updated_at,p.reviewer_id,p.reviewed_at FROM main.policy_contract p JOIN new_contract.underwriting_case u ON u.underwriting_case_no=p.underwriting_case_no JOIN new_contract.insurance_application a ON a.application_no=p.application_no WHERE u.contract_status_code='01' ORDER BY
p.application_no p.product_code p.policy_no
DESCASC,p.policy_no ASC LIMIT #{pageSize} OFFSET #{offset}
